<?php
/** FOURWARD coursework | Author: 韩羽宸 | Source-backed individual board with position-specific SVG radar. */
declare(strict_types=1);
$p=$data['player'];$s=$p['summary'];$labels=\Fourward\worldcup\models\PlayerBoard::METRICS;
$axes=array_values(array_filter($p['radar'],fn($a)=>$a['score']!==null));
$chart=count($axes)>=3&&$s['appearances']>0;
$point=static function(int $i,int $n,float $value,float $radius=122):array {$angle=-M_PI/2+2*M_PI*$i/$n;return [230+cos($angle)*$radius*$value/100,205+sin($angle)*$radius*$value/100];};
$polygon=static function(array $values)use($point):string {$out=[];foreach($values as $i=>$v){$xy=$point($i,count($values),(float)$v);$out[]=round($xy[0],2).','.round($xy[1],2);}return implode(' ',$out);};
?>
<div class="wc-breadcrumb"><a href="<?= e($url('teams',['id'=>$p['team_id']])) ?>#team-squad"><?= e($p['name_zh']) ?></a><span>/</span><span><?= e($p['name']) ?></span></div>
<section class="wc-player-hero"><div class="wc-player-identity"><?= $portrait($p,'large') ?><div><p class="wc-eyebrow">PLAYER PROFILE / WORLD CUP 2026</p><h2><?= e($p['name']) ?></h2><p><?= $flag($p['code'],$p['name_zh']) ?><a href="<?= e($url('teams',['id'=>$p['team_id']])) ?>"><?= e($p['name_zh']) ?></a><span><?= e($p['shirt_number']??'—') ?> 号 · <?= e($positions[$p['position']]??$p['position']) ?> · <?= e($p['position']) ?></span></p></div></div><a class="glass-button" href="<?= e($url('leaders',['position'=>$p['position']])) ?>">同位置球员榜 ↗</a></section>
<nav class="wc-section-nav wc-player-overview-nav" aria-label="球员面板分区"><a href="#season-overview">赛事总览</a><a href="#single-performance">单场发挥</a><a href="#player-match-log">逐场记录</a><a href="#player-events">球员事件</a></nav>
<div class="wc-team-summary wc-player-summary"><?php foreach(['appearances'=>'出场','starts'=>'首发'] as $key=>$label): ?><div><strong><?= e($s[$key]) ?></strong><span><?= e($label) ?></span></div><?php endforeach; ?><?php foreach(['goals'=>'进球','shots'=>'射门'] as $key=>$label): ?><div><strong><?= e($number($s['totals'][$key])) ?></strong><span><?= e($label) ?></span></div><?php endforeach; ?><div><strong><?= e($number($s['totals']['passes_completed'])) ?></strong><span>成功传球</span></div><div><strong><?= e($number($s['pass_completion_pct'],'%')) ?></strong><span>传球成功率</span></div></div>
<div class="wc-player-board" id="season-overview"><section class="wc-panel wc-radar-panel" data-position="<?= e($p['position']) ?>"><div class="wc-section-heading"><div><p class="wc-eyebrow">POSITIONAL DATA RADAR</p><h2><?= e($positions[$p['position']]??'球员') ?>数据雷达</h2></div><span class="wc-muted">本届 · 同位置比较</span></div>
<?php if($chart): ?><svg class="wc-radar" viewBox="0 0 460 410" role="img" aria-labelledby="radar-title radar-desc"><title id="radar-title"><?= e($p['name']) ?>的位置数据雷达</title><desc id="radar-desc">各项同位置最高值为100，实线为本球员，虚线为同位置均值；不是能力评分。原始数值见下表。</desc>
<?php foreach([25,50,75,100] as $level): ?><polygon class="wc-radar-grid" points="<?= e($polygon(array_fill(0,count($axes),$level))) ?>"/><?php endforeach; ?>
<?php foreach($axes as $i=>$a):$end=$point($i,count($axes),100);$label=$point($i,count($axes),100,162); ?><line class="wc-radar-spoke" x1="230" y1="205" x2="<?= e(round($end[0],2)) ?>" y2="<?= e(round($end[1],2)) ?>"/><text x="<?= e(round($label[0],2)) ?>" y="<?= e(round($label[1],2)) ?>" text-anchor="middle" dominant-baseline="middle"><?= e($a['label']) ?></text><?php endforeach; ?>
<polygon class="wc-radar-average" points="<?= e($polygon(array_column($axes,'average_score'))) ?>"/><polygon class="wc-radar-value" points="<?= e($polygon(array_column($axes,'score'))) ?>"/>
<?php foreach($axes as $i=>$a):$xy=$point($i,count($axes),$a['score']); ?><circle class="wc-radar-dot" cx="<?= e(round($xy[0],2)) ?>" cy="<?= e(round($xy[1],2)) ?>" r="3.5"><title><?= e($a['label'].' '.$number($a['value'],$a['unit']==='%'?'%':'')) ?></title></circle><?php endforeach; ?>
</svg><div class="wc-radar-legend"><span>本球员</span><span>同位置均值</span></div>
<?php else: ?><div class="wc-radar-empty"><h3><?= $s['appearances']===0?'本届尚未出场':'可比较的完整指标不足' ?></h3><p>暂不生成雷达图，避免将缺失数据当作零。</p></div><?php endif; ?>
<p class="wc-muted wc-fineprint">计数按场均比较，百分比保留原量纲；按同位置已出场球员的单项最高值归一化。小样本和对手差异会影响图形，图形面积不是综合能力评分。</p>
<?php if($p['position']==='GK'): ?><p class="wc-muted wc-fineprint">当前门将雷达侧重出球与比赛参与；尚无可靠的逐人扑救数据，不展示扑救率。</p><?php endif; ?>
<div class="wc-table-wrap"><table class="wc-radar-values"><thead><tr><th>比较指标</th><th>本人</th><th>同位置均值</th></tr></thead><tbody><?php foreach($p['radar'] as $a): ?><tr><th><?= e($a['label']) ?></th><td><?= e($number($a['value'],$a['unit']==='%'?'%':'')) ?></td><td><?= e($number($a['average'],$a['unit']==='%'?'%':'')) ?></td></tr><?php endforeach; ?></tbody></table></div>
</section>
<section class="wc-panel"><div class="wc-section-heading"><div><p class="wc-eyebrow">TOURNAMENT STATISTICS</p><h2>本届统计明细</h2></div><span class="wc-muted"><?= e($s['appearances']) ?> 次出场</span></div><?php $metricValues=$s['totals'];$metricCoverage=$s['coverage'];$metricPassPct=$s['pass_completion_pct'];require __DIR__.'/player-metric-grid.php'; ?><p class="wc-muted wc-fineprint">— 表示没有对应统计。部分覆盖的指标保留已有合计并显示覆盖场次，不进入雷达或完整榜单。进球不含乌龙球和点球大战；单场助攻、出场分钟暂缺。</p></section></div>
<?php require __DIR__.'/player-match.php'; ?>
<section class="wc-panel" id="player-match-log"><div class="wc-section-heading"><div><p class="wc-eyebrow">MATCH BY MATCH</p><h2>逐场表现</h2></div></div><div class="wc-table-wrap"><table><thead><tr><th>北京时间</th><th>对手</th><th>阶段</th><th>出场情况</th><th>进球</th><th>射门</th><th>成功传球 / 传球</th><th>个人本场</th></tr></thead><tbody><?php foreach($p['matches'] as $m): ?><tr><td><?= e($beijingTime($m['kickoff_at'])) ?></td><td><span class="wc-opponent"><?= $flag($m['opponent_code'],$m['opponent_name']) ?><?= e($m['opponent_name']) ?></span></td><td><?= e($m['stage_name']) ?></td><td><?= $m['appeared']===null?'名单未记录':($m['is_starter']?'首发':($m['appeared']?'替补出场':'未上场')) ?></td><td><?= e($number($m['goals'])) ?></td><td><?= e($number($m['shots'])) ?></td><td><?= e($number($m['passes_completed']).' / '.$number($m['passes_attempted'])) ?></td><td><a class="wc-back" href="<?= e($url('player',['id'=>$p['id'],'match_id'=>$m['id']])) ?>#single-performance">看本场 ↗</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="wc-panel" id="player-events"><div class="wc-section-heading"><div><p class="wc-eyebrow">RECORDED EVENTS</p><h2>球员事件</h2></div></div><div class="wc-player-event-summary"><?php foreach(['goal','own_goal','yellow_card','red_card','subbed_on','subbed_off'] as $type): ?><span><?= e($eventLabels[$type]) ?><b><?= e($p['event_counts'][$type]??0) ?></b></span><?php endforeach; ?></div><p class="wc-muted wc-fineprint">此处统计的是数据源中已记录的事件；未记录不能用来推断完整公平竞赛分。</p><?php if($p['events']): ?><ul class="wc-player-events"><?php foreach($p['events'] as $event): ?><li><a href="<?= e($url('matches',['id'=>$event['match_id']])) ?>">M<?= e($event['match_no']) ?></a><time><?= e($event['minute_label']) ?></time><span><?= e($eventLabels[$event['event_type']]) ?></span></li><?php endforeach; ?></ul><?php endif; ?></section>
